import {test,expect,type Page} from '@playwright/test';

test('B33 received report originals separate delivery attempts and preserve reading drafts',async({page},info)=>{
 await page.addInitScript(()=>{const Native=Worker;Reflect.set(window,'__b33ReportRequests',[]);window.Worker=new Proxy(Native,{construct(Type,args){const worker=Reflect.construct(Type,args),post=worker.postMessage.bind(worker);worker.postMessage=(message:unknown)=>{(Reflect.get(window,'__b33ReportRequests') as unknown[]).push(message);post(message);};return worker;}});});
 const start=async()=>{await page.goto('/');await page.getByLabel('演练任务').selectOption('INTEGRATED-FIELD-PACK-3');await page.getByLabel('时间方式').selectOption('research');await page.getByRole('button',{name:'开始演练',exact:true}).click();await expect(page.getByRole('region',{name:'综合现场地图',exact:true})).toHaveAttribute('data-regional-state','ready');};
 const observe=async()=>{await page.getByRole('button',{name:'下达移动命令',exact:true}).click();await page.getByLabel('推进到时刻（秒）').fill('267');await page.getByRole('button',{name:'推进时间',exact:true}).click();await page.getByRole('button',{name:'观察 A 参照',exact:true}).click();await page.getByLabel('推进到时刻（秒）').fill('289');await page.getByRole('button',{name:'推进时间',exact:true}).click();};
 await start();await expect(page.getByRole('region',{name:'已收报告原文',exact:true})).toContainText('尚未收到报告正文');await observe();const list=page.getByRole('region',{name:'已收报告原文',exact:true}),origin=list.getByRole('button',{name:'查看报告原文 R 观察 A 当地已完成',exact:true});await expect(list).toContainText('2 份报告');await page.getByLabel('移动目的地').selectOption('B');await page.getByLabel('推进到时刻（秒）').fill('400');await origin.click();const detail=page.getByRole('region',{name:'报告原文详情',exact:true});await expect(detail).toContainText('观测 288 秒');await expect(detail).toContainText('生成 288 秒');await expect(detail).toContainText('源报告时刻未知');await expect(detail).toContainText('表达精度：定性');await expect(detail).toContainText('观察年龄 1 秒');await expect(detail).toContainText('首次收到 289 秒');await expect(detail).toContainText('50 m 参照可见');await expect(detail).toContainText('100 m 参照不可见');await expect(detail).toContainText('方法不支持');const acceptedOrigin=list.getByRole('button',{name:'查看报告原文 R 观察 A 当地已接令',exact:true});await acceptedOrigin.click();await expect(detail).toContainText('观测 268 秒');await origin.click();await expect(detail).toContainText('观测 288 秒');await detail.getByRole('button',{name:'返回报告列表',exact:true}).click();await expect(origin).toBeFocused();await expect(page.getByLabel('移动目的地')).toHaveValue('B');await expect(page.getByLabel('推进到时刻（秒）')).toHaveValue('400');
 const issued=await page.evaluate(()=>Reflect.get(window,'__b33ReportRequests') as Array<{kind:string;envelope?:{intent:{kind:string}}}>);expect(issued.filter(request=>request.kind==='operate_integrated_field'&&['integrated_move','integrated_activity'].includes(request.envelope?.intent.kind??''))).toHaveLength(2);expect(issued.some(request=>request.kind==='management_pause')).toBe(false);
 // UI-only Transport fixture for a second delivery of the unchanged original.
 // Actual producer/replay duplication is separately exercised through Game.
 await page.addInitScript(()=>{const Native=Worker;window.Worker=new Proxy(Native,{construct(Type,args){const worker=Reflect.construct(Type,args);let injecting=false;worker.addEventListener('message',(event:MessageEvent)=>{if(injecting||event.data.view?.scenario_kind!=='play_integrated_field')return;const original=event.data.view.reports?.find((report:{body:{kind:string}})=>report.body.kind==='weather_observation');if(!original)return;const data=structuredClone(event.data),delivery=data.view.activity_reports.find((delivery:{report_ref:string})=>delivery.report_ref===original.ref.id);if(data.view.sim_time===400000){delivery.sent_at=399000;delivery.received_at=400000;const knowledge=data.view.knowledge.reports.find((item:{report_ref:string})=>item.report_ref===original.ref.id);knowledge.first_received_at=400000;knowledge.late=true;}data.view.activity_reports.push({...delivery,id:delivery.id+'-owned-redelivery',knowledge_seq:data.view.activity_reports.length+1});event.stopImmediatePropagation();injecting=true;try{worker.dispatchEvent(new MessageEvent('message',{data}));}finally{injecting=false;}});return worker;}});});
 await start();await observe();await expect(list).toContainText('2 份报告');await expect(origin).toHaveCount(1);await origin.click();await expect(detail).toContainText('2 次递交');await detail.getByRole('button',{name:'返回报告列表',exact:true}).click();await page.getByLabel('推进到时刻（秒）').fill('400');await page.getByRole('button',{name:'推进时间',exact:true}).click();await origin.click();await expect(detail).toContainText('观察年龄 112 秒');await expect(detail).toContainText('首次收到 400 秒');await expect(detail).toContainText('迟到材料；收到不刷新观察年龄');await expect(detail).toContainText('不据递交次数判断独立来源');await expect(page.getByRole('alert')).toHaveCount(0);await info.attach('report-original-and-delivery-boundaries.json',{body:JSON.stringify({actual_first_run:'real Worker report and return-focus/drafts',repeat_fixture:'Transport duplicate/late-delivery UI vectors only; real Game producer duplication and normal save/as_of covered in core',issued}),contentType:'application/json'});
});

