test('B33 terminal rejects forged identities and retries uncertain viewing with the original grant and payload',async({page},info)=>{
 await page.addInitScript(()=>{const Native=Worker;Reflect.set(window,'__b33TerminalRequests',[]);window.Worker=new Proxy(Native,{construct(Type,args){const worker=Reflect.construct(Type,args),post=worker.postMessage.bind(worker);let injecting=false,corruption=0,loseAck=true;worker.postMessage=(message:unknown)=>{(Reflect.get(window,'__b33TerminalRequests') as unknown[]).push(structuredClone(message));post(message);};worker.addEventListener('message',(event:MessageEvent)=>{if(injecting)return;let data=structuredClone(event.data);if(data.integrated_truth&&corruption<5){const step=corruption++;if(step===0)data.integrated_truth.run_id='foreign-run';if(step===1)data.integrated_truth.run_digest='a'.repeat(64);if(step===2)data.integrated_truth.finished_seq++;if(step===3)data.integrated_truth.grant.operation_id='foreign-grant';if(step===4)data.integrated_truth.facts.quantities.portable_energy_j.R++;}else if(data.integrated_truth_confirmation&&loseAck){loseAck=false;data={request_id:data.request_id,ok:false,code:'CHANNEL_UNCERTAIN'};}else return;event.stopImmediatePropagation();injecting=true;try{worker.dispatchEvent(new MessageEvent('message',{data}));}finally{injecting=false;}});return worker;}});});
 await terminalStart(page);await terminalAbort(page);await page.getByRole('button',{name:'查看任务复盘',exact:true}).click();const debrief=page.getByRole('region',{name:'任务复盘',exact:true}),facts=page.getByRole('region',{name:'终局事实',exact:true});for(let index=0;index<5;index++){await debrief.getByRole('button',{name:'揭示终局事实',exact:true}).click();await expect(debrief).toContainText('尚未取得可核验的终局事实');await expect(facts).toHaveCount(0);}await debrief.getByRole('button',{name:'揭示终局事实',exact:true}).click();await expect(facts).toContainText('24 J');await expect(facts).toContainText('6.5 J');await expect(debrief).toContainText('事实已显示，查看记录保存尚未确认');await debrief.getByRole('button',{name:'重试保存查看记录',exact:true}).click();await expect(debrief).toContainText('查看记录已确认保存');const requests=await page.evaluate(()=>Reflect.get(window,'__b33TerminalRequests') as Array<{kind:string;envelope?:{operation_id:string;payload_digest?:string}}>) ,reveals=requests.filter(request=>request.kind==='request_integrated_truth'),acks=requests.filter(request=>request.kind==='confirm_integrated_truth');expect(reveals).toHaveLength(6);expect(new Set(reveals.map(request=>request.envelope!.operation_id)).size).toBe(1);expect(acks).toHaveLength(2);expect(acks[0].envelope).toEqual(acks[1].envelope);expect(acks[0].envelope!.operation_id).toBe(reveals[0].envelope!.operation_id);await debrief.getByRole('button',{name:'关闭复盘',exact:true}).click();await page.getByRole('button',{name:'查看任务复盘',exact:true}).click();await expect(debrief).toContainText('查看记录已确认保存');await expect(page.getByRole('alert')).toHaveCount(0);await info.attach('terminal-forged-and-uncertain-carriers.json',{body:JSON.stringify({actual:'real terminal producer and confirmed IndexedDB metadata',fault_carrier:'Transport changes wrong run/digest/sequence/grant/quantity then loses first already-committed confirmation response only',requests}),contentType:'application/json'});
});

test('B33 terminal isolates an old pending truth response when changing to another run',async({page},info)=>{
 await page.addInitScript(()=>{const Native=Worker;Reflect.set(window,'__b33TerminalRequests',[]);window.Worker=new Proxy(Native,{construct(Type,args){const worker=Reflect.construct(Type,args),post=worker.postMessage.bind(worker);let injecting=false;worker.postMessage=(message:unknown)=>{(Reflect.get(window,'__b33TerminalRequests') as unknown[]).push(structuredClone(message));post(message);};worker.addEventListener('message',(event:MessageEvent)=>{if(injecting||!event.data.integrated_truth)return;event.stopImmediatePropagation();const data=structuredClone(event.data);Reflect.set(window,'__releaseOldTruth',()=>{injecting=true;try{worker.dispatchEvent(new MessageEvent('message',{data}));Reflect.set(window,'__oldTruthReleased',true);}finally{injecting=false;}});});return worker;}});});
 await terminalStart(page);await terminalAbort(page);await page.getByRole('button',{name:'查看任务复盘',exact:true}).click();await page.getByRole('button',{name:'揭示终局事实',exact:true}).click();await expect.poll(()=>page.evaluate(()=>typeof Reflect.get(window,'__releaseOldTruth'))).toBe('function');await page.getByRole('button',{name:'更换演练任务',exact:true}).click();await page.getByLabel('演练任务').selectOption('INTEGRATED-FIELD-PACK-3');await page.getByLabel('时间方式').selectOption('research');await page.getByRole('button',{name:'开始演练',exact:true}).click();await expect(page.getByRole('region',{name:'综合现场地图',exact:true})).toHaveAttribute('data-regional-state','ready');await page.evaluate(async()=>{Reflect.apply(Reflect.get(window,'__releaseOldTruth'),null,[]);await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));});await expect(page.getByRole('region',{name:'终局事实',exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'查看任务复盘',exact:true})).toBeDisabled();const requests=await page.evaluate(()=>Reflect.get(window,'__b33TerminalRequests') as Array<{kind:string}>);expect(requests.filter(request=>request.kind==='confirm_integrated_truth')).toHaveLength(0);await expect(page.getByRole('alert')).toHaveCount(0);await info.attach('terminal-old-response-isolation.json',{body:JSON.stringify({carrier:'actual grant saved; response delayed by Transport only until a new real run is shown',old_response_confirmed_in_new_run:false,requests}),contentType:'application/json'});
});

test('B33 persistence preserves history and same-condition runs with confirmed exposure sources and uncertain fairness retry',async({page},info)=>{
 await page.addInitScript(()=>{const Native=Worker;let failed=false;window.Worker=new Proxy(Native,{construct(Type,args){const worker=Reflect.construct(Type,args);let injecting=false;worker.addEventListener('message',(event:MessageEvent)=>{if(event.data.ok&&event.data.view)Reflect.set(window,'__b33PersistenceView',event.data.view);if(injecting||failed||!event.data.integrated_fairness)return;failed=true;event.stopImmediatePropagation();injecting=true;try{worker.dispatchEvent(new MessageEvent('message',{data:{request_id:event.data.request_id,ok:false,code:'CHANNEL_UNCERTAIN'}}));}finally{injecting=false;}});return worker;}});});
 await terminalStart(page);const fairness=page.getByRole('region',{name:'本场景公平记录',exact:true});await expect(fairness).toContainText('公平记录待核');await fairness.getByRole('button',{name:'重试核对公平记录',exact:true}).click();await expect(fairness).toContainText('尚无已确认的终局事实查看记录');const original=await page.evaluate(()=>Reflect.get(window,'__b33PersistenceView').run_id as string);
 await page.getByRole('button',{name:'查看历史节点',exact:true}).click();await expect(page.getByRole('button',{name:'下达移动命令',exact:true})).toBeDisabled();await page.getByRole('button',{name:'返回当前行动',exact:true}).click();await terminalAbort(page);await page.getByRole('button',{name:'查看任务复盘',exact:true}).click();await page.getByRole('button',{name:'揭示终局事实',exact:true}).click();await expect(page.getByRole('region',{name:'任务复盘',exact:true})).toContainText('查看记录已确认保存');await page.getByRole('button',{name:'关闭复盘',exact:true}).click();
 await page.getByRole('button',{name:'重开这场演练',exact:true}).click();await page.getByRole('button',{name:'确认重开',exact:true}).click();await expect.poll(()=>page.evaluate(()=>Reflect.get(window,'__b33PersistenceView').source_run)).toBe(original);await expect(page.getByRole('button',{name:'查看上一场记录',exact:true})).toBeVisible();await expect(fairness).toContainText('非首次公平');await expect(fairness).toContainText(original);const next=await page.evaluate(()=>Reflect.get(window,'__b33PersistenceView') as {run_id:string;source_run:string;sim_time:number;paused:boolean;reports:unknown[]});expect(next).toMatchObject({source_run:original,sim_time:0,paused:true,reports:[]});expect(next.run_id).not.toBe(original);await expect(page.getByRole('region',{name:'已收报告原文',exact:true})).toContainText('尚未收到报告正文');
 await page.getByRole('button',{name:'查看上一场记录',exact:true}).click();await expect(page.getByRole('button',{name:'下达移动命令',exact:true})).toBeDisabled();await expect.poll(()=>page.evaluate(()=>Reflect.get(window,'__b33PersistenceView').run_id)).toBe(original);await page.getByRole('button',{name:'返回当前行动',exact:true}).click();await expect.poll(()=>page.evaluate(()=>Reflect.get(window,'__b33PersistenceView').run_id)).toBe(next.run_id);await expect(fairness).toContainText('非首次公平');await expect(page.getByRole('alert')).toHaveCount(0);await info.attach('history-clone-fairness.json',{body:JSON.stringify({original,next,carrier:'real Game/Worker/Transport/IndexedDB; only first fairness response faulted'}),contentType:'application/json'});
});

test('B33 persistence keeps narrow layout and keyboard return usable with long Chinese drafts and unknown source time',async({page},info)=>{
 await page.setViewportSize({width:390,height:844});await terminalStart(page);const top=await page.locator('.integrated-workbench .topbar').evaluate(node=>({content:node.scrollWidth,visible:node.clientWidth}));expect.soft(top.content,'narrow header controls must fit without horizontal clipping').toBeLessThanOrEqual(top.visible);const workspace=await page.locator('.integrated-workbench .mission-body').evaluate(node=>({content:node.scrollWidth,visible:node.clientWidth}));expect.soft(workspace.content,'narrow workspace must not hide either map or controls horizontally').toBeLessThanOrEqual(workspace.visible);const mapSize=await page.getByRole('region',{name:'综合现场地图',exact:true}).boundingBox();expect.soft(mapSize?.width,'narrow map remains readable').toBeGreaterThanOrEqual(200);expect.soft(mapSize?.height,'narrow map remains readable').toBeGreaterThanOrEqual(160);await page.screenshot({path:info.outputPath('narrow-headquarters-initial.png')});const reason=page.getByLabel('研判理由（可选）');await reason.fill('依照总部当时收到的材料核对，来源时刻未知时保留未知。'.repeat(12));await reason.focus();const entry=page.getByRole('button',{name:'终止当前任务',exact:true});await entry.scrollIntoViewIfNeeded();await entry.focus();await page.keyboard.press('Enter');const dialog=page.getByRole('dialog',{name:'确认终止当前任务',exact:true});await expect(dialog.getByRole('button',{name:'确认终止',exact:true})).toBeFocused();await page.keyboard.press('Escape');await expect(entry).toBeFocused();await expect(reason).toHaveValue('依照总部当时收到的材料核对，来源时刻未知时保留未知。'.repeat(12));
 await page.getByRole('button',{name:'安排资料校验与准备',exact:true}).click();await page.getByRole('button',{name:'W 检查 B',exact:true}).click();await terminalAdvance(page,'32');await page.getByRole('button',{name:'查看报告原文 W 检查 B 当地已完成',exact:true}).click();const detail=page.getByRole('region',{name:'报告原文详情',exact:true});await expect(detail).toContainText('源报告时刻未知');await page.getByRole('button',{name:'返回报告列表',exact:true}).press('Enter');await expect(page.getByRole('button',{name:'查看报告原文 W 检查 B 当地已完成',exact:true})).toBeFocused();
 const visited:string[]=[];for(let index=0;index<18;index++){await page.keyboard.press('Tab');visited.push(await page.evaluate(()=>document.activeElement?.tagName+':'+document.activeElement?.textContent?.slice(0,60)));}expect(new Set(visited).size).toBeGreaterThan(5);await page.screenshot({path:info.outputPath('narrow-keyboard-long-Chinese.png'),fullPage:true});await page.setViewportSize({width:1440,height:900});await expect(page.getByRole('region',{name:'综合现场地图',exact:true})).toHaveAttribute('data-regional-state','ready');await page.screenshot({path:info.outputPath('desktop-after-keyboard.png')});await expect(page.getByRole('alert')).toHaveCount(0);await info.attach('keyboard-focus-walk.json',{body:JSON.stringify({viewport:{width:390,height:844},visited,unknown_source_preserved:true}),contentType:'application/json'});
});